<script setup>
import { onMounted, watch } from 'vue'; import { useRoute } from 'vue-router'; import { showToast } from 'vant'; import AppNavBar from '@/components/common/AppNavBar.vue'; import ProductSwiper from '@/components/product/ProductSwiper.vue'; import LoadingView from '@/components/common/LoadingView.vue'; import EmptyView from '@/components/common/EmptyView.vue'; import { useService } from '@/composables/useService'; import { useCart } from '@/composables/useCart'; import { useNavigator } from '@/composables/useNavigator'; import { formatPrice } from '@/utils/formatter'
const route = useRoute(); const { service, loadDetail } = useService(); const { add } = useCart(); const { goMerchantInfo } = useNavigator(); const load = () => loadDetail(route.params.serviceId); onMounted(load); watch(() => route.params.serviceId, load)
const addCart = () => { if (!service.value) return; add(service.value); showToast('已加入清单') }
</script>
<template><main class="mobile-page detail-page"><AppNavBar title="服务详情"/><LoadingView v-if="service === null"/><section v-else-if="service" class="detail-content"><ProductSwiper :images="service.images" ratio="1 / 1"/><article class="card-surface info"><van-tag round type="success">{{service.tag}}</van-tag><h1>{{service.title}}</h1><p>{{service.description}}</p><strong>{{formatPrice(service.price)}} <small v-if="service.referencePrice">参考价 {{formatPrice(service.referencePrice)}}</small></strong></article><button class="merchant-card card-surface" @click="goMerchantInfo(service.merchantId)"><span>服务商</span><b>{{service.merchantName}}</b><span>查看商户介绍 ›</span></button><article class="card-surface description"><h2>服务说明</h2><p>{{service.description}}。提交清单后可与商户进一步确认具体服务安排。</p><h2>购买须知</h2><p>服务以商户最终确认的信息为准，请在结算前核对数量与价格。</p></article></section><EmptyView v-else description="服务不存在"/><footer v-if="service" class="action-bar"><van-button block round type="primary" size="large" @click="addCart">加入清单</van-button></footer></main></template>
<style scoped lang="scss">.detail-page{padding-bottom:76px}.detail-content{padding:12px}.info{margin-top:12px}.info h1{margin:14px 0 8px;font-size:22px}.info p,.description p{color:#6f7d76;line-height:1.7}.info strong{color:#ee0a24;font-size:22px}.info small{color:#969799;font-size:12px;font-weight:400}.merchant-card{display:flex;width:100%;align-items:center;justify-content:space-between;margin-top:12px;border:0;text-align:left}.merchant-card span{color:#829089;font-size:12px}.merchant-card b{color:#27342f}.description{margin-top:12px}.description h2{font-size:16px}.action-bar{position:fixed;z-index:20;right:0;bottom:0;left:0;max-width:640px;margin:auto;padding:10px 16px calc(10px + env(safe-area-inset-bottom));background:#fff}</style>
